package com.naimat.autotimelinesync;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import android.net.Uri;import java.io.*;import java.util.concurrent.atomic.AtomicBoolean;
public final class ExportService extends Service {
 public interface Listener{void changed();}public static volatile Listener listener;public static volatile boolean running;public static volatile String phase="",error="";public static volatile int percent;public static volatile long started;public static volatile Uri result;public static final AtomicBoolean cancel=new AtomicBoolean();public static Project project;public static int width,height;public static boolean quality;public static Uri destination;
 private PowerManager.WakeLock lock;private final Handler handler=new Handler(Looper.getMainLooper());
 public static void notifyUI(){Listener l=listener;if(l!=null)new Handler(Looper.getMainLooper()).post(l::changed);}
 public android.os.IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int startId){if(i!=null&&"cancel".equals(i.getAction())){cancel.set(true);return START_NOT_STICKY;}if(running)return START_NOT_STICKY;if(project==null||destination==null){stopSelf();return START_NOT_STICKY;}running=true;cancel.set(false);error="";result=null;percent=0;started=System.currentTimeMillis();phase="Preparing export";NotificationManager manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("export","Video export",NotificationManager.IMPORTANCE_LOW));Notification n=notification();if(Build.VERSION.SDK_INT>=29)startForeground(3,n,Build.VERSION.SDK_INT>=35?ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROCESSING:ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(3,n);lock=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"ATS:Export");lock.acquire(6*60*60*1000L);notifyUI();Project snapshot=project;Uri target=destination;new Thread(()->{File parent=new File(getCacheDir(),"export-jobs"),job=new File(parent,"job-"+System.currentTimeMillis());job.mkdirs();try{File output=VideoEngine.export(this,snapshot,job,width,height,quality,cancel,(p,value)->{phase=p;percent=value;notifyUI();handler.post(()->manager.notify(3,notification()));});try(InputStream in=new FileInputStream(output);OutputStream out=getContentResolver().openOutputStream(target,"wt")){if(out==null)throw new IOException("Cannot write selected output.");byte[]b=new byte[262144];int k;while((k=in.read(b))!=-1){AudioEngine.check(cancel);out.write(b,0,k);}}result=target;phase="Export complete";percent=100;}catch(InterruptedException e){phase="Export cancelled";error="";deleteNewOutput(target);}catch(Throwable e){phase="Export failed";error=e.getMessage()==null?e.toString():e.getMessage();deleteNewOutput(target);}finally{try{MediaFiles.clean(job,parent);}catch(Exception e){if(error.isEmpty())error="Temporary cleanup: "+e.getMessage();}running=false;project=null;notifyUI();handler.post(()->{if(lock!=null&&lock.isHeld())lock.release();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();});}},"ATS export").start();return START_NOT_STICKY;}
 private void deleteNewOutput(Uri u){try{android.provider.DocumentsContract.deleteDocument(getContentResolver(),u);}catch(Exception ignored){}}
 private Notification notification(){PendingIntent launch=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent action=PendingIntent.getService(this,1,new Intent(this,ExportService.class).setAction("cancel"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"export").setSmallIcon(android.R.drawable.stat_sys_upload).setContentTitle("Auto Timeline Sync • "+percent+"%").setContentText(phase).setContentIntent(launch).setProgress(100,percent,false).setOngoing(true).addAction(new Notification.Action.Builder(null,"Cancel",action).build()).build();}
}
